```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;

  return function (...args) {
    const now = Date.now();
    const remaining = wait - (now - last);

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = now;
      fn.apply(this, args);
    } else if (!timer) {
      // Trailing call so the final scroll position isn't dropped
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

const onScroll = throttle(() => {
  console.log('scrollY:', window.scrollY);
}, 200);

window.addEventListener('scroll', onScroll, { passive: true });
```

The handler fires immediately on the first scroll event, then at most once per 200 ms while scrolling continues. The trailing timer ensures one last call after scrolling stops, so your handler sees the final position.

`{ passive: true }` tells the browser the handler won't call `preventDefault()`, which keeps scrolling smooth.

To remove it later, use `window.removeEventListener('scroll', onScroll)`, passing the same throttled reference.

