If the request takes longer than 5 seconds, the promise rejects with a `TimeoutError`:

```js
try {
  const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
  const data = await response.json();
} catch (err) {
  if (err.name === 'TimeoutError') {
    console.error('Request timed out');
  } else {
    throw err;
  }
}
```

The timeout covers the whole request, including reading the body, so a slow `response.json()` will abort too.

`AbortSignal.timeout()` is supported in all current browsers and Node 17.3+. For older environments, or if you also need to cancel manually, use an `AbortController`:

```js
const controller = new AbortController();
const timer = setTimeout(() => controller.abort(), 5000);

try {
  const response = await fetch(url, { signal: controller.signal });
  const data = await response.json();
} finally {
  clearTimeout(timer);
}
```

Here the abort rejects with an `AbortError` rather than `TimeoutError`.

```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function encodeCursor(row) {
  return Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');
}

function decodeCursor(cursor) {
  const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
  if (typeof ts !== 'string' || Number.isNaN(Date.parse(ts)) || !/^\d+$/.test(String(id))) {
    throw new Error('bad cursor');
  }
  return [ts, id];
}

router.get('/orders', async (req, res, next) => {
  try {
    let limit = DEFAULT_LIMIT;
    if (req.query.limit !== undefined) {
      limit = Number(req.query.limit);
      if (!Number.isInteger(limit) || limit < 1) {
        return res.status(400).json({ error: 'limit must be a positive integer' });
      }
      limit = Math.min(limit, MAX_LIMIT);
    }

    const params = [];
    let where = '';
    if (req.query.cursor !== undefined) {
      try {
        params.push(...decodeCursor(req.query.cursor));
      } catch {
        return res.status(400).json({ error: 'invalid cursor' });
      }
      where = 'WHERE (created_at, id) < ($1::timestamptz, $2::bigint)';
    }

    // Fetch one extra row to know whether another page exists
    params.push(limit + 1);
    const { rows } = await pool.query(
      `SELECT id, customer_id, status, total, created_at,
              created_at::text AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $${params.length}`,
      params
    );

    const hasMore = rows.length > limit;
    const page = hasMore ? rows.slice(0, limit) : rows;
    const nextCursor = hasMore ? encodeCursor(page[page.length - 1]) : null;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: nextCursor,
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

The client calls `GET /orders?limit=20`, then passes the returned `next_cursor` back as `GET /orders?limit=20&cursor=...` until `next_cursor` is `null`.

It needs a matching index so each page is an index range scan rather than a sort:

```sql
CREATE INDEX orders_created_at_id_idx ON orders (created_at DESC, id DESC);
```

- **Assumed schema:** I guessed the column names (`customer_id`, `status`, `total`), that `id` is a `bigint`, and that `created_at` is a `timestamptz`. Change the select list and the `$2::bigint` cast (and the id check in `decodeCursor`) if yours differ, for example for a UUID id.
- **Timestamp precision:** the cursor uses `created_at::text` rather than the JavaScript `Date` that `pg` returns. PostgreSQL stores microseconds and `Date` keeps only milliseconds, so a cursor built from the `Date` would skip or repeat rows at page boundaries.
- **Tie-breaking:** the row comparison `(created_at, id) < ($1, $2)` uses `id` to order rows that share a `created_at`, so no rows are skipped or duplicated between pages.
- **Cursor trust:** the cursor is only base64-encoded, so clients can read and forge it. The values are validated and passed as query parameters, so that is safe, but sign it with an HMAC if you want it tamper-proof.

