```go
package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, short, usage, def string
	isBool                  bool
	b                       *bool
	s                       *string
}

func (f *flagDef) label() string {
	l := "    --" + f.name
	if f.short != "" {
		l = "-" + f.short + ", --" + f.name
	}
	if !f.isBool {
		l += " <value>"
	}
	return l
}

type argDef struct {
	name, usage string
	s           *string
}

type Parser struct {
	name  string
	flags []*flagDef
	args  []*argDef
	rest  []string
}

func NewParser(name string) *Parser {
	return &Parser{name: name}
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	b := new(bool)
	p.flags = append(p.flags, &flagDef{name: name, short: short, usage: usage, isBool: true, b: b})
	return b
}

// String defines a flag that takes a value. short may be empty.
func (p *Parser) String(name, short, def, usage string) *string {
	s := new(string)
	*s = def
	p.flags = append(p.flags, &flagDef{name: name, short: short, usage: usage, def: def, s: s})
	return s
}

// Arg defines a required positional argument, filled in definition order.
func (p *Parser) Arg(name, usage string) *string {
	s := new(string)
	p.args = append(p.args, &argDef{name: name, usage: usage, s: s})
	return s
}

// Rest returns positional arguments beyond those defined with Arg.
func (p *Parser) Rest() []string {
	return p.rest
}

func (p *Parser) lookup(name string, long bool) *flagDef {
	if name == "" {
		return nil
	}
	for _, f := range p.flags {
		if (long && f.name == name) || (!long && f.short == name) {
			return f
		}
	}
	return nil
}

func (p *Parser) Parse(args []string) error {
	var positional []string

	for i := 0; i < len(args); i++ {
		a := args[i]

		// Everything after "--" is positional
		if a == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if a == "-" || !strings.HasPrefix(a, "-") {
			positional = append(positional, a)
			continue
		}

		long := strings.HasPrefix(a, "--")
		trimmed := strings.TrimPrefix(a, "-")
		if long {
			trimmed = strings.TrimPrefix(trimmed, "-")
		}
		name, value, hasValue := strings.Cut(trimmed, "=")

		if (long && name == "help") || (!long && name == "h") {
			p.Usage(os.Stdout)
			return ErrHelp
		}

		f := p.lookup(name, long)
		if f == nil {
			return fmt.Errorf("unknown flag: %s", a)
		}

		if f.isBool {
			*f.b = true
			if hasValue {
				v, err := strconv.ParseBool(value)
				if err != nil {
					return fmt.Errorf("invalid boolean for --%s: %q", f.name, value)
				}
				*f.b = v
			}
			continue
		}

		if !hasValue {
			if i+1 >= len(args) {
				return fmt.Errorf("flag --%s requires a value", f.name)
			}
			i++
			value = args[i]
		}
		*f.s = value
	}

	if len(positional) < len(p.args) {
		return fmt.Errorf("missing argument: <%s>", p.args[len(positional)].name)
	}
	for i, a := range p.args {
		*a.s = positional[i]
	}
	p.rest = positional[len(p.args):]
	return nil
}

// Usage writes a help message built from the flag and argument definitions.
func (p *Parser) Usage(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [flags]", p.name)
	for _, a := range p.args {
		fmt.Fprintf(w, " <%s>", a.name)
	}
	fmt.Fprintln(w)

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	if len(p.args) > 0 {
		fmt.Fprintln(tw, "\nArguments:")
		for _, a := range p.args {
			fmt.Fprintf(tw, "  %s\t%s\n", a.name, a.usage)
		}
	}
	fmt.Fprintln(tw, "\nFlags:")
	for _, f := range p.flags {
		usage := f.usage
		if !f.isBool && f.def != "" {
			usage += fmt.Sprintf(" (default %q)", f.def)
		}
		fmt.Fprintf(tw, "  %s\t%s\n", f.label(), usage)
	}
	fmt.Fprintln(tw, "  -h, --help\tshow this help")
	tw.Flush()
}

func main() {
	p := NewParser("copy")
	verbose := p.Bool("verbose", "v", "print each file as it is copied")
	output := p.String("output", "o", "out.txt", "where to write the result")
	src := p.Arg("src", "source file")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, ErrHelp) {
			os.Exit(0)
		}
		fmt.Fprintln(os.Stderr, "error:", err)
		p.Usage(os.Stderr)
		os.Exit(2)
	}

	fmt.Println("verbose:", *verbose)
	fmt.Println("output: ", *output)
	fmt.Println("src:    ", *src)
	fmt.Println("rest:   ", p.Rest())
}
```

Running `copy --help` should print:

```
Usage: copy [flags] <src>

Arguments:
  src  source file

Flags:
  -v, --verbose         print each file as it is copied
  -o, --output <value>  where to write the result (default "out.txt")
  -h, --help            show this help
```

It accepts `--output file`, `--output=file`, `-o file`, and `-o=file`, and flags and positionals can be mixed in any order.

Limitations:

- **String values only:** value flags are strings, so convert with `strconv` at the call site if you need numbers.
- **No combined short flags:** `-vo file` is not split into `-v -o file`.
- **Leading dashes:** anything starting with `-` is treated as a flag, so pass a value like `-5` as `--output=-5`, or put positionals after `--`.

