export type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly pending: Array<() => Promise<void>> = [];
  private idleResolvers: Array<() => void> = [];
  private active = 0;

  constructor(
    private readonly concurrency: number,
    private readonly maxRetries = 3,
  ) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
  }

  /** Queues a job. Resolves with its result, or rejects once all retries have failed. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.runWithRetries(job).then(resolve, reject));
      this.next();
    });
  }

  /** Resolves when nothing is running and nothing is waiting. */
  onIdle(): Promise<void> {
    if (this.isIdle) return Promise.resolve();
    return new Promise((resolve) => this.idleResolvers.push(resolve));
  }

  get size(): number {
    return this.pending.length + this.active;
  }

  private get isIdle(): boolean {
    return this.active === 0 && this.pending.length === 0;
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.active++;
      void run().finally(() => {
        this.active--;
        this.next();
      });
    }

    if (this.isIdle) {
      const resolvers = this.idleResolvers;
      this.idleResolvers = [];
      for (const resolve of resolvers) resolve();
    }
  }

  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.maxRetries) throw err;
      }
    }
  }
}
